    """Get a configuration value from either model_config (pydantic v2) or class Config (v1)."""
    # Try model_config first (pydantic v2)
    model_config = getattr(settings, "model_config", None)
    if model_config is not None:
        val = getattr(model_config, key, None)
        if val is not None:
            return val
    # Fallback to class Config (pydantic v1 style)
    config_class = getattr(settings.__class__, "Config", None)
    if config_class is not None:
        return getattr(config_class, key, None)
    return None

